fn find(table: &[Fact], name: &str) -> Option<Quantity> {
    table
        .iter()
        .find(|fact| fact.0 == name)
        .map(|fact| Quantity {
            value: Complex64::new(fact.1, 0.0),
            dimension: fact.2,
        })
}

/// Exact shipped unit symbols only; caller owns generic prefix fallback.
pub fn lookup(name: &str) -> Option<Quantity> {
    find(UNITS, name)
}
pub fn evaluate(name: &str) -> Option<Quantity> {
    lookup(name)
}
pub fn names() -> impl Iterator<Item = &'static str> {
    UNITS.iter().map(|fact| fact.0)
}

/// Physical constants remain separate from the UNIT label namespace.
pub fn constant_lookup(name: &str) -> Option<Quantity> {
    find(CONSTANTS, name)
}
pub fn constant_names() -> impl Iterator<Item = &'static str> {
    CONSTANTS.iter().map(|fact| fact.0)
}
